// renko candle
//
function RenkoCalculate(){this.BrickSize=0.05;//固定大小
this.SourceData;this.LastData;this.ATR={Count:14,BrickSize:0.05};//使用ATR计算砖块大小
this.BrickSizeType=1;//0=固定 1=ATR动态计算
this.Symbol;this.FloatPrecision=2;//品种小数位数
this.ClassName="RenkoCalculate";this.SetOption=function(option){if(!option)return;if(IFrameSplitOperator.IsNumber(option.BrickSize))this.BrickSize=option.BrickSize;if(IFrameSplitOperator.IsNumber(option.BrickSizeType))this.BrickSizeType=option.BrickSizeType;if(option.ATR){var item=option.ATR;if(IFrameSplitOperator.IsNumber(item.Count))this.ATR.Count=item.Count;}};this.CalculateByClose=function(sourceData)//使用收盘价计算
{var bindData=new ChartData();bindData.Data=[];bindData.Right=sourceData.Right;bindData.Period=sourceData.Period;bindData.DataType=sourceData.DataType;bindData.Symbol=sourceData.symbol;if(!IFrameSplitOperator.IsNonEmptyArray(sourceData.Data))return bindData;var brickSize=this.BrickSize;if(this.BrickSizeType==1)brickSize=this.ATR.BrickSize;var kItem=sourceData.Data[0];this.LastData=HistoryData.Copy(kItem);for(var i=1;i<sourceData.Data.length;){var kItem=sourceData.Data[i];var movementFromClose=kItem.Close-this.LastData.Close;var movementFromOpen=kItem.Close-this.LastData.Open;if(Math.abs(movementFromClose)>=brickSize&&Math.abs(movementFromOpen)>=brickSize){var vol=0;if(movementFromClose>0||movementFromOpen>0){var yClose=this.LastData.Close;var open=Math.max(this.LastData.Close,this.LastData.Open);var close=open+brickSize;var high=close;var low=open;vol=kItem.Vol;}else{var yClose=this.LastData.Close;var open=Math.min(this.LastData.Close,this.LastData.Open);var close=open-brickSize;var high=open;var low=close;vol=kItem.Vol;}var item=new HistoryData();item.Date=kItem.Date;item.Time=kItem.Time;item.YClose=yClose;item.Open=open;item.High=high;item.Low=low;item.Close=close;item.Vol=this.LastData.Vol+vol;bindData.Data.push(item);this.LastData.YClose=item.YClose;this.LastData.Open=item.Open;this.LastData.High=item.High;this.LastData.Low=item.Low;this.LastData.Close=item.Close;this.LastData.Date=item.Date;this.LastData.Time=item.Time;this.LastData.Vol=0;}else{this.LastData.Vol+=kItem.Vol;//量需要累加
++i;}}return bindData;};this.RecvHistoryData=function(sourceData,option)//历史日线数据
{this.Symbol=option.Symbol;this.SourceData=sourceData;this.FloatPrecision=GetfloatPrecision(this.Symbol);if(this.BrickSizeType==1)this.CalculateATR();return this.CalculateByClose(sourceData);};this.Clear=function(){this.SourceData=null;this.LastData=null;this.Symbol=null;};//获取配置信息
this.GetTitle=function(){if(this.BrickSizeType==1){var text='Renko [ATR('+this.ATR.Count+'), '+this.ATR.BrickSize+']';}else{var text='Renko [Traditional, '+this.BrickSize+']';}return text;};//通过ATR计算砖块大小
//真实范围 = MAX（最高价 (1) – 最低价 (1)；最高价 (1) – 收盘价 (2)；收盘价 (2) – 最低价 (1)）
this.CalculateATR=function(){if(!IFrameSplitOperator.IsNonEmptyArray(this.SourceData.Data))return;var kData=this.SourceData.Data;var count=kData.length;var aryData=[];for(var i=count-1,j=0;i>=0&&j<this.ATR.Count;--i,++j){var item=kData[i];var value=Math.max(item.High-item.Low,item.High-item.Close,item.Close-item.Low);aryData.push(value);}//使用MA计算，也可以使用SMA计算
var total=0;for(var i=0;i<aryData.length;++i){total+=aryData[i];}var brickSize=total/aryData.length;var value=brickSize.toFixed(this.FloatPrecision);this.ATR.BrickSize=parseFloat(value);};}/////////////////////////////////////////////////////////////////////////
//kagi candle
//
function KagiCalculate(){this.newMethod=RenkoCalculate;//派生
this.newMethod();delete this.newMethod;this.ClassName="KagiCalculate";this.BrickSizeType=0;this.BrickSize=0.5;//固定大小
this.RecvHistoryData=function(sourceData,option)//历史日线数据
{this.Symbol=option.Symbol;this.SourceData=sourceData;this.FloatPrecision=GetfloatPrecision(this.Symbol);if(this.BrickSizeType==1)this.CalculateATR();return this.CalculateByClose(sourceData);};this.CalculateByClose=function(sourceData){var bindData=new ChartData();bindData.Data=[];bindData.Right=sourceData.Right;bindData.Period=sourceData.Period;bindData.DataType=sourceData.DataType;bindData.Symbol=sourceData.symbol;if(!IFrameSplitOperator.IsNonEmptyArray(sourceData.Data))return bindData;var brickSize=this.BrickSize;if(this.BrickSizeType==1)brickSize=this.ATR.BrickSize;var kItem=sourceData.Data[0];var kagiItem=HistoryData.Copy(kItem);kagiItem.High=kagiItem.Low=kItem.Close;kagiItem.StartItem=kItem;kagiItem.Direction=0;//1 上 2=下
var T_MergeKData=function T_MergeKData(dest,src){dest.Vol+=src.Vol;dest.Amount+=src.Amount;};var index=1;for(;index<sourceData.Data.length;++index)//确定好方向
{var kItem=sourceData.Data[index];if(kItem.Close>kagiItem.Close){kagiItem.Direction=1;kagiItem.Close=kItem.Close;kagiItem.EndItem=kItem;kagiItem.High=kItem.Close;break;}else if(kItem.Close<kagiItem.Close){kagiItem.Direction=2;kagiItem.Close=kItem.Close;kagiItem.EndItem=kItem;kagiItem.Low=kItem.Close;break;}}var changeItem=null;for(++index;index<sourceData.Data.length;++index){var kItem=sourceData.Data[index];if(kagiItem.Direction==1)//上
{if(kItem.Close>=kagiItem.High){kagiItem.Close=kItem.Close;kagiItem.High=kItem.Close;kagiItem.EndItem=kItem;changeItem=null;}else{if(!changeItem){changeItem=HistoryData.Copy(kItem);changeItem.High=changeItem.Low=kItem.Close;}else{changeItem.Close=kItem.Close;if(changeItem.Low>kItem.Close)changeItem.Low=kItem.Close;}if(Math.abs(changeItem.Low-kagiItem.High)>brickSize)//达到变盘点
{bindData.Data.push(kagiItem);var newItem=HistoryData.Copy(kItem);newItem.High=kagiItem.High;newItem.Low=kItem.Close;newItem.Direction=2;//1 上 2=下
newItem.StartItem=kItem;kagiItem=newItem;changeItem=null;}}}else if(kagiItem.Direction==2)//下
{if(kItem.Close<=kagiItem.Low){kagiItem.Close=kItem.Close;kagiItem.Low=kItem.Close;kagiItem.EndItem=kItem;}else{if(!changeItem){changeItem=HistoryData.Copy(kItem);changeItem.High=changeItem.Low=kItem.Close;}else{changeItem.Close=kItem.Close;if(changeItem.High<kItem.Close)changeItem.High=kItem.Close;}if(Math.abs(changeItem.High-kagiItem.Low)>brickSize)//达到变盘点
{bindData.Data.push(kagiItem);var newItem=HistoryData.Copy(kItem);newItem.High=kItem.Close;newItem.Low=kagiItem.Low;newItem.Direction=1;//1 上 2=下
newItem.StartItem=kItem;kagiItem=newItem;changeItem=null;}}}}return bindData;};//获取配置信息
this.GetTitle=function(){if(this.BrickSizeType==1){var text='Kagi [ATR('+this.ATR.Count+'), '+this.ATR.BrickSize+']';}else{var text='Kagi [Traditional]';}return text;};}//////////////////////////////////////////////////////////////////
//   HeikinAshi
//
function HeikinAshiCalculate(){this.SourceData;this.Symbol;this.FloatPrecision=2;//品种小数位数
this.ClassName="HeikinAshiCalculate";this.Clear=function(){this.SourceData=null;this.LastData=null;this.Symbol=null;};this.RecvHistoryData=function(sourceData,option)//历史日线数据
{this.Symbol=option.Symbol;this.SourceData=sourceData;this.FloatPrecision=GetfloatPrecision(this.Symbol);return this.Calculate(sourceData);};this.GetTitle=function(){return"Heikin Ashi";};this.Calculate=function(sourceData){var bindData=new ChartData();bindData.Data=[];bindData.Right=sourceData.Right;bindData.Period=sourceData.Period;bindData.DataType=sourceData.DataType;bindData.Symbol=sourceData.symbol;if(!IFrameSplitOperator.IsNonEmptyArray(sourceData.Data))return bindData;var lastKItem=null;var yClose=null;for(var i=0;i<sourceData.Data.length;++i){var kItem=sourceData.Data[i];var newItem=HistoryData.Copy(kItem);if(!lastKItem){newItem.Open=(kItem.Close+kItem.Open)/2;newItem.Close=(kItem.Close+kItem.Open+kItem.High+kItem.Low)/4;yClose=newItem.Close;}else{newItem.Close=(kItem.Close+kItem.Open+kItem.High+kItem.Low)/4;newItem.Open=(lastKItem.Close+lastKItem.Open)/2;newItem.YClose=yClose;newItem.High=Math.max(newItem.Close,newItem.Open,kItem.High);newItem.Low=Math.min(newItem.Close,newItem.Open,kItem.Low);yClose=newItem.Close;}lastKItem=kItem;bindData.Data.push(newItem);}return bindData;};}//////////////////////////////////////////////////////////////////
//  line break
// 
function LineBreakCalcuate(){this.SourceData;this.Symbol;this.FloatPrecision=2;//品种小数位数
this.LineCount=3;this.ClassName="LineBreakCalcuate";this.Clear=function(){this.SourceData=null;this.LastData=null;this.Symbol=null;};this.GetTitle=function(){return'Line Break ['+this.LineCount+']';};this.RecvHistoryData=function(sourceData,option)//历史日线数据
{this.Symbol=option.Symbol;this.SourceData=sourceData;this.FloatPrecision=GetfloatPrecision(this.Symbol);return this.CalculateByClose(sourceData);};//计算前N个周期的最大最小值
this.CalculatePreviousKLine=function(preKLine){for(var i=0;i<preKLine.Data.length;++i){var item=preKLine.Data[i];if(i==0){preKLine.High=item.High;preKLine.Low=item.Low;}else{if(preKLine.High<item.High)preKLine.High=item.High;if(preKLine.Low<item.Low)preKLine.Low=item.Low;}preKLine.Date=item.Date;preKLine.Time=item.Time;preKLine.Vol+=item.Vol;preKLine.Amount+=item.Amount;}};//使用收盘价计算
/*
        If the close of the daily bar is higher than the high of the previous white line, draw a new white line with the open equal to the previous line’s high, and the close equal to the close of the current daily bar.
        If the close of the daily bar is lower than the low of the last three lines, draw a new red line with the open equal to the previous line’s low and the close equal to the close of the current daily bar.
        If neither of the above two conditions are met, no new line is produced.
    */this.CalculateByClose=function(sourceData){var bindData=new ChartData();bindData.Data=[];bindData.Right=sourceData.Right;bindData.Period=sourceData.Period;bindData.DataType=sourceData.DataType;bindData.Symbol=sourceData.symbol;if(!IFrameSplitOperator.IsNonEmptyArray(sourceData.Data))return bindData;var index=0;var preItem={High:null,Low:null,Date:null,Time:null,Direction:0};for(;index<sourceData.Data.length&&index<this.LineCount;++index){var kItem=sourceData.Data[index];if(i==0){preItem.High=kItem.High;preItem.Low=kItem.Low;}else{if(preItem.High<kItem.High)preItem.High=kItem.High;if(preItem.Low>kItem.Low)preItem.Low=kItem.Low;}preItem.Date=kItem.Date;preItem.Time=kItem.Time;preItem.Vol+=kItem.Vol;preItem.Amount+=kItem.Amount;}for(var i=index;i<sourceData.Data.length;++i){var kItem=sourceData.Data[i];if(kItem.Close>preItem.High)//阳线
{var item=new HistoryData();item.YClose=preItem.Low;if(preItem)item.Open=preItem.High;else item.Open=preItem.High;item.Close=kItem.Close;item.Low=Math.min(item.Open,item.Close);item.High=Math.max(item.Open,item.Close);item.Date=kItem.Date;item.Time=kItem.Time;item.Vol=kItem.Vol;item.Amount=kItem.Amount;item.Direction=1;//阳线
bindData.Data.push(item);//if (preItem && preItem.Direction==1) preItem.Close=preItem.High;
//else if (preItem && preItem.Direction==2) preItem.Close=preItem.Low;
preItem=item;}else if(kItem.Close<preItem.Low)//阴线
{var item=new HistoryData();item.YClose=preItem.High;if(preItem)item.Open=preItem.Low;else item.Open=preItem.Low;item.Close=kItem.Close;item.Low=Math.min(item.Open,item.Close);item.High=Math.max(item.Open,item.Close);item.Date=kItem.Date;item.Time=kItem.Time;item.Vol=kItem.Vol;item.Amount=kItem.Amount;item.Direction=2;//阴线
bindData.Data.push(item);//if (preItem && preItem.Direction==1) preItem.Close=preItem.High;
//else if (preItem && preItem.Direction==2) preItem.Close=preItem.Low;
preItem=item;}else{if(preItem){if(preItem.Direction==1){//if (preItem.High<kItem.High) preItem.High=kItem.High;
}else if(preItem.Direction==2){//if (preItem.Low>kItem.Low) preItem.Low=kItem.Low;
}preItem.Vol+=kItem.Vol;preItem.Amount+=kItem.Amount;}}}return bindData;};}/////////////////////////////////////////////////////////////////////////////////////////////
