this.INTPART=function(data){var result=null;if(Array.isArray(data)){result=[];for(var i in data){var item=data[i];if(this.IsNumber(item))result[i]=parseInt(item);else result[i]=null;}}else if(this.IsNumber(data)){result=parseInt(data);}return result;};//用法:CONST(A),取A最后的值为常量.
//例如:CONST(INDEXC),表示取大盘现价
this.CONST=function(data){if(Array.isArray(data)){var count=data.length;if(count>0)return data[count-1];return null;}else{return data;}};//当前值是近多少周期内的最大值.
//用法: TOPRANGE(X):X是近多少周期内X的最大值
//例如: TOPRANGE(HIGH)表示当前最高价是近多少周期内最高价的最大值
this.TOPRANGE=function(data){if(this.IsNumber(data))return 0;var result=[];if(Array.isArray(data)){var count=data.length;for(var i=count-1;i>=0;--i){result[i]=0;var item=data[i];if(!this.IsNumber(item))continue;var value=0;for(var j=i-1;j>=0;--j){if(data[j]>item){break;}++value;}result[i]=value;}}return result;};//当前值是近多少周期内的最小值.
//用法:LOWRANGE(X):X是近多少周期内X的最小值
