//用法:FINDLOW(VAR,N,M,T):VAR在N日前的M天内第T个最低价
this.FINDLOW=function(data,n,m,t){if(this.IsNumber(data))return data;var result=[];if(Array.isArray(data)){var count=data.length;for(var i=count-1;i>=0;--i){result[i]=null;var aryValue=[];for(var j=n;j<m;++j){var index=i-j;if(index<0)break;var item=data[index];if(this.IsNumber(item))aryValue.push(item);}if(aryValue.length>0){aryValue.sort(function(a,b){return a-b;});var index=t-1;if(index<0)index=0;else if(index>=aryValue.length)index=aryValue.length-1;result[i]=aryValue[index];}}}return result;};//N周期前的M周期内的第T个最大值.
//用法:FINDHIGH(VAR,N,M,T):VAR在N日前的M天内第T个最高价
this.FINDHIGH=function(data,n,m,t){if(this.IsNumber(data))return data;var result=[];if(Array.isArray(data)){var count=data.length;for(var i=count-1;i>=0;--i){result[i]=null;var aryValue=[];for(var j=n;j<m;++j){var index=i-j;if(index<0)break;var item=data[index];if(this.IsNumber(item))aryValue.push(item);}if(aryValue.length>0){aryValue.sort(function(a,b){return b-a;});var index=t-1;if(index<0)index=0;else if(index>=aryValue.length)index=aryValue.length-1;result[i]=aryValue[index];}}}return result;};//N周期前的M周期内的第T个最大值到当前周期的周期数.
