this.FINDHIGHBARS=function(data,n,m,t){if(this.IsNumber(data))return m-n-t;var result=[];if(Array.isArray(data)){var count=data.length;for(var i=count-1;i>=0;--i){result[i]=null;var aryValue=[];for(var j=n;j<m;++j){var index=i-j;if(index<0)break;var item=data[index];if(this.IsNumber(item))aryValue.push({Value:item,Period:j});}if(aryValue.length>0){aryValue.sort(function(a,b){return b.Value-a.Value;});var index=t-1;if(index<0)index=0;else if(index>=aryValue.length)index=aryValue.length-1;result[i]=aryValue[index].Period;}}}return result;};//N周期前的M周期内的第T个最小值到当前周期的周期数.
//用法:FINDLOWBARS(VAR,N,M,T):VAR在N日前的M天内第T个最低价到当前周期的周期数.
this.FINDLOWBARS=function(data,n,m,t){if(this.IsNumber(data))return m-n-t;var result=[];if(Array.isArray(data)){var count=data.length;for(var i=count-1;i>=0;--i){result[i]=null;var aryValue=[];for(var j=n;j<m;++j){var index=i-j;if(index<0)break;var item=data[index];if(this.IsNumber(item))aryValue.push({Value:item,Period:j});}if(aryValue.length>0){aryValue.sort(function(a,b){return a.Value-b.Value;});var index=t-1;if(index<0)index=0;else if(index>=aryValue.length)index=aryValue.length-1;result[i]=aryValue[index].Period;}}}return result;};//求高值名次.
//用法:HOD(X,N):求当前X数据是N周期内的第几个高值,N=0则从第一个有效值开始.
//例如:HOD(HIGH,20)返回是20日的第几个高价
this.HOD=function(data,n){var result=[];if(IFrameSplitOperator.IsNumber(data))return 1;if(Array.isArray(data)){var count=data.length;for(var i=count-1;i>=0;--i){var value=data[i];if(!IFrameSplitOperator.IsNumber(value))continue;if(Array.isArray(n))var subCount=parseInt(n[i]);else var subCount=parseInt(n);if(n<=0)subCount=i;var index=1;for(var j=i-1,k=1;j>=0&&k<subCount;--j,++k){var item=data[j];if(IFrameSplitOperator.IsNumber(item)&&item>value)++index;}result[i]=index;}}return result;};//求低值名次.
//用法:LOD(X,N):求当前X数据是N周期内的第几个低值,N=0则从第一个有效值开始.
//例如:LOD(LOW,20)返回是20日的第几个低价
this.LOD=function(data,n){var result=[];if(IFrameSplitOperator.IsNumber(data))return 1;if(Array.isArray(data)){var count=data.length;for(var i=count-1;i>=0;--i){var value=data[i];if(!IFrameSplitOperator.IsNumber(value))continue;if(Array.isArray(n))var subCount=parseInt(n[i]);else var subCount=parseInt(n);if(n<=0)subCount=i;var index=1;for(var j=i-1,k=1;j>=0&&k<subCount;--j,++k){var item=data[j];if(IFrameSplitOperator.IsNumber(item)&&item<value)++index;}result[i]=index;}}return result;};//属于未来函数,下一次条件成立到当前的周期数.
//用法:BARSNEXT(X):下一次X不为0到现在的天数
