this.PARTLINE=function(args){var drawData=[];var result={DrawData:drawData,DrawType:'PARTLINE'};if(args.length<3)return result;var data=args[0];var condition=[];for(var i=1;i<args.length&&i+1<args.length;i+=2){condition.push({Cond:args[i],RGB:args[i+1]});}for(var i in data){var drawItem={Value:null,RGB:null};drawData[i]=drawItem;var value=data[i];if(!this.IsNumber(value))continue;var rgb=null;for(var j in condition){var item=condition[j];if(Array.isArray(item.Cond)){if(i<item.Cond.length&&item.Cond[i]){rgb=item.RGB;break;}}else{if(this.IsNumber(item.Cond)&&item.Cond)//单数值条件
{rgb=item.RGB;break;}}}if(rgb){drawItem.Value=value;drawItem.RGB=rgb;}}return result;};//函数:FILLRGN,根据条件用RGN颜色填充区域
