this.FILLRGN2=function(args){var drawData=[];var result={DrawData:drawData,DrawType:'FILLRGN2'};if(args.length<4)return result;var price=args[0];var price2=args[1];var condition=[];for(var i=2;i<args.length&&i+1<args.length;i+=2){condition.push({Cond:args[i],Color:args[i+1]});}for(var i=0;i<this.SymbolData.Data.Data.length;++i){drawData[i]=null;var drawItem={Value:null,Value2:null,Color:null};for(var j in condition){var item=condition[j];if(Array.isArray(item.Cond)){if(i<item.Cond.length&&item.Cond[i]){drawItem.Color=item.Color;break;}}else{if(this.IsNumber(item.Cond)&&item.Cond)//单数值条件
{drawItem.Color=item.Color;break;}}}if(!drawItem.Color)continue;if(Array.isArray(price)){if(i>=price.length)continue;if(!this.IsNumber(price[i]))continue;drawItem.Value=price[i];}else if(this.IsNumber(price)){drawItem.Value=price;}else{continue;}if(Array.isArray(price2)){if(i>=price2.length)continue;if(!this.IsNumber(price2[i]))continue;drawItem.Value2=price2[i];}else if(this.IsNumber(price2)){drawItem.Value2=price2;}else{continue;}drawData[i]=drawItem;}return result;};//用法:FLOATRGN(PRICE,WIDTH,COND1,COLOR1,COND2,COLOR2...),以PRICE为基础填充宽度为WIDTH像素的区域,WIDTH为负则向下填充,当COND1条件满足时,用COLOR1颜色,当COND2条件满足时,用COLOR2颜色,否则不填充,从COND1之后的参数均可以省略,最多可以有10组条件
