this.FLOATRGN=function(args){var drawData=[];var result={DrawData:drawData,DrawType:'FLOATRGN'};if(args.length<4)return result;var price=args[0];var width=args[1];var condition=[];for(var i=2;i<args.length&&i+1<args.length;i+=2){condition.push({Cond:args[i],Color:args[i+1]});}for(var i=0;i<this.SymbolData.Data.Data.length;++i){drawData[i]=null;var drawItem={Value:null,Value2:null,Color:null};for(var j in condition){var item=condition[j];if(Array.isArray(item.Cond)){if(i<item.Cond.length&&item.Cond[i]){drawItem.Color=item.Color;break;}}else{if(this.IsNumber(item.Cond)&&item.Cond)//单数值条件
{drawItem.Color=item.Color;break;}}}if(!drawItem.Color)continue;if(Array.isArray(price)){if(i>=price.length)continue;if(!this.IsNumber(price[i]))continue;drawItem.Value=price[i];}else if(this.IsNumber(price)){drawItem.Value=price;}else{continue;}if(Array.isArray(width)){if(i>=width.length)continue;if(!this.IsNumber(width[i]))continue;drawItem.Value2=width[i];}else if(this.IsNumber(width)){drawItem.Value2=width;}else{continue;}drawData[i]=drawItem;}return result;};//函数:FILLTOPRGN / FILLBOTTOMRGN 根据条件填充顶部或底部区域
