this.DRAWSL=function(condition,data,slope,len,direct){var drawData={Data:[],Option:[]};var result={DrawData:drawData,DrawType:'DRAWSL'};var isNumber=this.IsNumber(data);if(Array.isArray(condition)){for(var i in condition){drawData.Data[i]=null;if(!condition[i])continue;if(isNumber){drawData.Data[i]=data;drawData.Option[i]={Slope:slope,Length:len,Direct:direct};}else{if(i<data.length&&this.IsNumber(data[i])){drawData.Data[i]=data[i];drawData.Option[i]={Slope:slope,Length:len,Direct:direct};}}}}else{if(condition){var count=this.SymbolData.Data.Data.length;for(var i=0;i<count;++i){drawData.Data[i]=null;if(isNumber){drawData.Data[i]=data;drawData.Option[i]={Slope:slope,Length:len,Direct:direct};}else{if(i<data.length&&this.IsNumber(data[i])){drawData.Data[i]=data[i];drawData.Option[i]={Slope:slope,Length:len,Direct:direct};}}}}}return result;};//含义:在图形上绘制垂直线。
