function LocalJsonDataIndex(name,args,option){this.newMethod=ScriptIndex;//派生
this.newMethod(name,null,args,null);delete this.newMethod;this.JsonData;//json格式数据
if(option.JsonData)this.JsonData=option.JsonData;this.RequestData=function(hqChart,windowIndex,hisData){if(!this.JsonData){console.warn("[LocalJsonDataIndex::RequestData] JsonData is null");if(param.HQChart.ScriptErrorCallback)param.HQChart.ScriptErrorCallback('json 数据不能为空');return;}this.OutVar=this.FittingData(this.JsonData,hisData);this.BindData(hqChart,windowIndex,hisData);};this.FittingData=function(jsonData,hisData){outVar=jsonData.OutVar;date=jsonData.Date;time=jsonData.Time;result=[];for(i in outVar){item=outVar[i];JSConsole.Complier.Log('[LocalJsonDataIndex::FittingData] item',item);if(item.Type!=0&&item.Type!=3)//复杂的图形不支持
{console.warn("[LocalJsonDataIndex::FittingData] can't support ",item.Name,item.Type);continue;}var indexData=[];outVarItem={Name:item.Name,Type:item.Type};for(j in item.Data){var indexItem=new SingleData();//单列指标数据
indexItem.Date=date[j];if(time&&j<time.length)indexItem.Time=time[j];indexItem.Value=item.Data[j];indexData.push(indexItem);}if(hisData.Period<4)var aryFittingData=hisData.GetFittingData(indexData);//数据和主图K线拟合
else var aryFittingData=hisData.GetMinuteFittingData(indexData);//数据和主图K线拟合
var bindData=new ChartData();bindData.Data=aryFittingData;outVarItem.Data=bindData.GetValue();result.push(outVarItem);}return result;};}////////////////////////////////////////////////////////////////////////
