this.NetworkFilter;//数据接口
this.IsApiPeriod=false;if(obj){if(obj.Name)this.Name=obj.Name;if(obj.Script)this.Script=obj.Script;if(obj.ID)this.ID=obj.ID;if(obj.Args)this.Arguments=obj.Args;if(obj.ErrorCallback)this.ErrorCallback=obj.ErrorCallback;if(obj.FinishCallback)this.FinishCallback=obj.FinishCallback;if(obj.IsSectionMode)this.IsSectionMode=obj.IsSectionMode;if(obj.NetworkFilter)this.NetworkFilter=obj.NetworkFilter;if(IFrameSplitOperator.IsBool(obj.IsApiPeriod))this.IsApiPeriod=obj.IsApiPeriod;}//执行脚本
